-- v4.4.1 Platform Administration, Admin Agent HA, upgrade and containment.
DECLARE PROCEDURE ddl(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
BEGIN
  ddl('CREATE TABLE CX_ADMIN_AGENT_GROUPS (GROUP_ID VARCHAR2(128) PRIMARY KEY,GROUP_KEY VARCHAR2(128) NOT NULL UNIQUE,STATUS VARCHAR2(32) DEFAULT ''ACTIVE'' NOT NULL,PRODUCTION_POLICY CHAR(1) DEFAULT ''Y'' NOT NULL,CURRENT_TERM NUMBER(19,0) DEFAULT 0 NOT NULL,LEADER_MEMBER_ID VARCHAR2(128),LEADER_LEASE_EXPIRES_AT TIMESTAMP,FENCING_TOKEN NUMBER(19,0) DEFAULT 0 NOT NULL,CONFIGURATION_STATE VARCHAR2(32) DEFAULT ''VALID'' NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_ADMIN_AGENT_MEMBERS (MEMBER_ID VARCHAR2(128) PRIMARY KEY,GROUP_ID VARCHAR2(128) NOT NULL,AGENT_ID VARCHAR2(128) NOT NULL,ADMISSION_PATH VARCHAR2(32) NOT NULL,STATUS VARCHAR2(32) DEFAULT ''CANDIDATE'' NOT NULL,VOTING_ENABLED CHAR(1) DEFAULT ''N'' NOT NULL,WEIGHT NUMBER(19,0) DEFAULT 1 NOT NULL,NODE_ID VARCHAR2(256),PUBLIC_KEY_DIGEST VARCHAR2(128),CANDIDATE_SINCE TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,APPROVED_AT TIMESTAMP,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT UK_ADMIN_MEMBER UNIQUE(GROUP_ID,AGENT_ID))');
  ddl('CREATE TABLE CX_ADMIN_ENROLLMENTS (ENROLLMENT_ID VARCHAR2(128) PRIMARY KEY,GROUP_ID VARCHAR2(128),ADMISSION_PATH VARCHAR2(32) NOT NULL,AGENT_ID VARCHAR2(128),NODE_ID VARCHAR2(256),PUBLIC_KEY_DIGEST VARCHAR2(128) NOT NULL,PACKAGE_DIGEST VARCHAR2(128) NOT NULL,STATUS VARCHAR2(32) DEFAULT ''CANDIDATE'' NOT NULL,REASON VARCHAR2(2000) NOT NULL,REQUESTED_BY VARCHAR2(128) NOT NULL,EXPIRES_AT TIMESTAMP NOT NULL,APPROVED_BY VARCHAR2(128),CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_ADMIN_QUORUM_SNAPSHOTS (SNAPSHOT_ID VARCHAR2(128) PRIMARY KEY,GROUP_ID VARCHAR2(128) NOT NULL,TERM NUMBER(19,0) NOT NULL,MEMBERS_JSON CLOB NOT NULL,TOTAL_WEIGHT NUMBER(19,0) NOT NULL,REQUIRED_COUNT NUMBER(19,0) NOT NULL,REQUIRED_WEIGHT NUMBER(19,0) NOT NULL,DECISION VARCHAR2(32),DECISION_REASON VARCHAR2(2000),CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_ADMIN_LEADER_EVIDENCE (EVIDENCE_ID VARCHAR2(128) PRIMARY KEY,GROUP_ID VARCHAR2(128) NOT NULL,MEMBER_ID VARCHAR2(128) NOT NULL,OLD_TERM NUMBER(19,0),NEW_TERM NUMBER(19,0) NOT NULL,OLD_FENCING_TOKEN NUMBER(19,0),NEW_FENCING_TOKEN NUMBER(19,0) NOT NULL,EVENT_TYPE VARCHAR2(64) NOT NULL,DETAIL_JSON CLOB DEFAULT ''{}'' NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_MANAGEMENT_ARTIFACTS (ARTIFACT_ID VARCHAR2(128) PRIMARY KEY,ARTIFACT_KEY VARCHAR2(256) NOT NULL,ARTIFACT_VERSION VARCHAR2(64) NOT NULL,ARTIFACT_KIND VARCHAR2(64) NOT NULL,CONTENT_DIGEST VARCHAR2(128) NOT NULL,SIGNATURE VARCHAR2(2048) NOT NULL,CLASSIFICATION VARCHAR2(32) DEFAULT ''INTERNAL'' NOT NULL,SECRET_FREE CHAR(1) DEFAULT ''Y'' NOT NULL,STATUS VARCHAR2(32) DEFAULT ''PUBLISHED'' NOT NULL,STORAGE_ADAPTER VARCHAR2(32) DEFAULT ''PEER'' NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT UK_MGMT_ARTIFACT UNIQUE(ARTIFACT_KEY,ARTIFACT_VERSION))');
  ddl('CREATE TABLE CX_MANAGEMENT_ARTIFACT_RECEIPTS (RECEIPT_ID VARCHAR2(128) PRIMARY KEY,ARTIFACT_ID VARCHAR2(128) NOT NULL,NODE_ID VARCHAR2(256) NOT NULL,RECEIVED_DIGEST VARCHAR2(128),SIGNATURE_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,AVAILABILITY_STATE VARCHAR2(32) DEFAULT ''MISSING'' NOT NULL,DETAIL_JSON CLOB DEFAULT ''{}'' NOT NULL,RECEIVED_AT TIMESTAMP,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT UK_ARTIFACT_RECEIPT UNIQUE(ARTIFACT_ID,NODE_ID))');
  ddl('CREATE TABLE CX_UPGRADE_PLANS (UPGRADE_ID VARCHAR2(128) PRIMARY KEY,PACKAGE_VERSION VARCHAR2(64) NOT NULL,EDITION VARCHAR2(32) NOT NULL,PACKAGE_DIGEST VARCHAR2(128) NOT NULL,SIGNATURE_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,PREFLIGHT_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,APPROVAL_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,ROLLOUT_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,STATUS VARCHAR2(32) DEFAULT ''STAGED'' NOT NULL,REASON VARCHAR2(2000) NOT NULL,CREATED_BY VARCHAR2(128) NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_UPGRADE_NODES (UPGRADE_NODE_ID VARCHAR2(128) PRIMARY KEY,UPGRADE_ID VARCHAR2(128) NOT NULL,NODE_ID VARCHAR2(256) NOT NULL,STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,ACTIVE_WORK_COUNT NUMBER(19,0) DEFAULT 0 NOT NULL,OLD_VERSION VARCHAR2(64),NEW_VERSION VARCHAR2(64),SKILL_STATE VARCHAR2(32) DEFAULT ''UNCHANGED'' NOT NULL,HEALTH_STATE VARCHAR2(32) DEFAULT ''UNKNOWN'' NOT NULL,EVIDENCE_JSON CLOB DEFAULT ''{}'' NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT UK_UPGRADE_NODE UNIQUE(UPGRADE_ID,NODE_ID))');
  ddl('CREATE TABLE CX_SKILL_DISTRIBUTION (DISTRIBUTION_ID VARCHAR2(128) PRIMARY KEY,UPGRADE_ID VARCHAR2(128) NOT NULL,AGENT_ID VARCHAR2(128) NOT NULL,SKILL_VERSION VARCHAR2(64) NOT NULL,MESSAGE_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,ACKNOWLEDGEMENT_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,ACTIVATION_STATE VARCHAR2(32) DEFAULT ''OLD_VERSION'' NOT NULL,DRIFT_STATE VARCHAR2(32) DEFAULT ''UNKNOWN'' NOT NULL,EVIDENCE_JSON CLOB DEFAULT ''{}'' NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT UK_SKILL_DISTRIBUTION UNIQUE(UPGRADE_ID,AGENT_ID,SKILL_VERSION))');
  ddl('CREATE TABLE CX_AGENT_CONTAINMENT_COMMANDS (COMMAND_ID VARCHAR2(128) PRIMARY KEY,AGENT_ID VARCHAR2(128) NOT NULL,INSTANCE_ID VARCHAR2(128) NOT NULL,REQUESTED_STATE VARCHAR2(32) NOT NULL,CONTROL_GENERATION NUMBER(19,0) NOT NULL,NONCE_DIGEST VARCHAR2(128) NOT NULL,ISSUER_PRINCIPAL_ID VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,EXPIRES_AT TIMESTAMP NOT NULL,SIGNATURE VARCHAR2(2048) NOT NULL,AUTHORITY_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,AGENT_ACK_STATE VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL,INFRASTRUCTURE_ACK_STATE VARCHAR2(32) DEFAULT ''NOT_CONFIGURED'' NOT NULL,CLEANUP_EVIDENCE_JSON CLOB DEFAULT ''{}'' NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_WEB_SESSION_POLICIES (POLICY_KEY VARCHAR2(32) PRIMARY KEY,IDLE_TIMEOUT_SECONDS NUMBER(19,0) NOT NULL,ABSOLUTE_TIMEOUT_SECONDS NUMBER(19,0) NOT NULL,VERSION NUMBER(19,0) DEFAULT 1 NOT NULL,UPDATED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_WEB_SESSION_POLICY_HISTORY (HISTORY_ID VARCHAR2(128) PRIMARY KEY,POLICY_KEY VARCHAR2(32) NOT NULL,VERSION NUMBER(19,0) NOT NULL,IDLE_TIMEOUT_SECONDS NUMBER(19,0) NOT NULL,ABSOLUTE_TIMEOUT_SECONDS NUMBER(19,0) NOT NULL,CHANGED_BY VARCHAR2(128) NOT NULL,REASON VARCHAR2(2000) NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE TABLE CX_API_CURSORS (CURSOR_ID VARCHAR2(128) PRIMARY KEY,PRINCIPAL_ID VARCHAR2(128) NOT NULL,RESOURCE_KEY VARCHAR2(64) NOT NULL,FILTER_DIGEST VARCHAR2(128) NOT NULL,SORT_KEY VARCHAR2(256) NOT NULL,PAGE_SIZE NUMBER(19,0) NOT NULL,POSITION_KEY VARCHAR2(256),EXPIRES_AT TIMESTAMP NOT NULL,CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)');
  ddl('CREATE INDEX IDX_ADMIN_MEMBER_GROUP ON CX_ADMIN_AGENT_MEMBERS(GROUP_ID,STATUS,VOTING_ENABLED,WEIGHT)');
  ddl('CREATE INDEX IDX_CONTAINMENT_INSTANCE ON CX_AGENT_CONTAINMENT_COMMANDS(INSTANCE_ID,CONTROL_GENERATION,AUTHORITY_STATE)');
  ddl('CREATE INDEX IDX_UPGRADE_NODES ON CX_UPGRADE_NODES(UPGRADE_ID,STATE,NODE_ID)');
END;
/
DECLARE
  v_nullable CHAR(1);
  PROCEDURE ddl(s VARCHAR2) IS BEGIN EXECUTE IMMEDIATE s; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1430 THEN RAISE; END IF; END;
BEGIN
  ddl('ALTER TABLE CX_ADMIN_ENROLLMENTS ADD (REQUESTED_BY VARCHAR2(128))');
  UPDATE CX_ADMIN_ENROLLMENTS SET REQUESTED_BY='SYSTEM_LEGACY' WHERE REQUESTED_BY IS NULL;
  SELECT NULLABLE INTO v_nullable FROM USER_TAB_COLUMNS
   WHERE TABLE_NAME='CX_ADMIN_ENROLLMENTS' AND COLUMN_NAME='REQUESTED_BY';
  IF v_nullable='Y' THEN
    EXECUTE IMMEDIATE 'ALTER TABLE CX_ADMIN_ENROLLMENTS MODIFY (REQUESTED_BY NOT NULL)';
  END IF;
END;
/
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'admin_channel_ha' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'Y','Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'controlled_upgrade' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'Y','Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'agent_containment' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'Y','Y');
MERGE INTO CX_PLATFORM_CAPABILITIES d USING (SELECT 'session_policy' CAPABILITY_KEY FROM DUAL) s ON (d.CAPABILITY_KEY=s.CAPABILITY_KEY) WHEN NOT MATCHED THEN INSERT (CAPABILITY_KEY,MANDATORY,ENABLED) VALUES (s.CAPABILITY_KEY,'Y','Y');
